// Everhour on a personal API key: every operation of Everhour's API (developers.everhour.com/openapi.json), plus tags
// and the team, which the spec leaves out. actions.json is generated by `bun scripts/openapi-actions.ts everhour`;
// projects, tasks, sections, timers, time, clients, estimates and invoices start automations by webhook (triggers.ts),
// expenses, schedule, time off, timesheet approvals and clock-ins by polling (polls/everhour.ts).
import { z } from "zod";
import type { OwnApp } from "../index";
import { type Api, call, rest, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export const api: Api = {
  name: "Everhour",
  base: "https://api.everhour.com",
  tokenHelp: "Everhour → your profile (app.everhour.com/#/account/profile) → API key at the bottom",
  // ponytail: a dead key gets 403 "Access denied", but so can a call the person's role may not make, so only a 401 marks the connection for reconnecting
  auth: (key) => ({ "X-Api-Key": key }),
};

const ME = { method: "GET", path: "/users/me", query: [], headers: [] };
const spec = await specActions(new URL("./actions.json", import.meta.url), api);

export const everhour: OwnApp = {
  app: "everhour",
  name: "Everhour",
  logo: "/logos/everhour.svg",
  keyField: {
    label: "API key",
    help: "In Everhour, click your name → My Profile (app.everhour.com/#/account/profile) and copy the API key at the bottom of the page. Emplio can then see and change whatever your Everhour role allows; an admin's key covers the whole team's time, invoices and approvals.",
    placeholder: "1a2b-3c4d-5e6f78-9a0b1c-2d3e4f5a",
  },
  async check(key) {
    const me = (await call(api, key, ME, {})) as { name?: string; email?: string };
    return me.name || me.email || "Everhour";
  },
  push: {
    events,
    triggers,
    start: (key, connection) => watch(api, key, connection),
    stop: (key, id) => unwatch(api, key, id),
    receive,
    wanted,
  },
  actions: {
    ...spec,
    // the profile carries the person's own API key; it never needs to reach the chat
    get_user_profile: {
      ...spec.get_user_profile!,
      run: async (i, key) => {
        const { apiKey: _, ...me } = (await spec.get_user_profile!.run(i, key)) as Record<string, unknown>;
        return me;
      },
    },
    list_tags: rest(api, "GET", "/tags", "List the team's tags: id, name and color. Tags label tasks (task_create and update_task take their ids).", z.object({})),
    list_teams: rest(api, "GET", "/team", "The Everhour team (workspace) this key belongs to: its id, name, owner, working days and hours, plan and settings.", z.object({})),
  },
};
